"""Ledger rows for generated files, written to a per-group fragment so parallel builders never edit the same file.

    from common import ledger
    ledger.add("models", "assets/models/cottage.glb", kind="model", generator=__file__,
               used_in="Hamlet: houses", seed=1)

writes/updates one row (same columns as assets/LEDGER.csv, no header) in a per-group row file:
  * by default build/ledger-rows/models.csv: scratch, outside the repository's tracked files, so rebuilding never
    rewrites a tracked file. tools/build-assets.sh clears it before each group runs and checks it against
    LEDGER.csv; merge it with  python3 tools/merge-ledger-rows.py --build
  * with ASSET_LEDGER_FRAGMENTS=1 (or --ledger-fragments on the generator's command line) the tracked fragment
    assets/src/ledger-rows/models.csv instead, for builders working in parallel who hand rows to the lead.
    assets/models/cottage.glb,model,"generated by assets/src/models/cottage.py (seed 1); script written by Claude Opus 5.5",self-made,,Hamlet: houses,2026-11-24,no
Rows are keyed on `item`: re-running a generator replaces its row (keeping the original date if nothing else
changed), so the fragment stays stable. `verified` stays 'no' until you pass verified=True after ticking the
done checklist in docs/asset-pipeline.md.
python3 tools/check-ledger.py --fragments checks LEDGER.csv plus all fragments; tools/merge-ledger-rows.py
moves fragment rows into LEDGER.csv (the lead's step).
"""
import csv
import datetime
import io
import os
from pathlib import Path

from . import ROOT, SRC, rel

HEADER = ["item", "kind", "source", "licence", "url", "used_in", "date_checked", "verified"]
import sys

FRAG_DIR = SRC / "ledger-rows"                 # tracked fragments (only when asked)
BUILD_DIR = ROOT / "build" / "ledger-rows"     # scratch rows from every generator run (default)
WRITER = os.environ.get("ASSET_SCRIPT_WRITER", "Claude Opus 5.5")


def _read(path):
    if not path.exists():
        return []
    with path.open(newline="", encoding="utf-8") as f:
        return [r for r in csv.reader(f) if any(c.strip() for c in r)]


def to_fragments():
    return os.environ.get("ASSET_LEDGER_FRAGMENTS") == "1" or "--ledger-fragments" in sys.argv[1:]


def _target(group):
    return (FRAG_DIR if to_fragments() else BUILD_DIR) / f"{group}.csv"


def add(group, item, kind, generator, used_in, seed=None, verified=False, writer=WRITER, licence="self-made",
        url="", note="", date=None):
    """Upsert the row for `item` (path or repo-relative string) into build/ledger-rows/<group>.csv (default) or
    assets/src/ledger-rows/<group>.csv (ASSET_LEDGER_FRAGMENTS=1). The date is kept from LEDGER.csv when the
    rest of the row is unchanged there, so a rebuild does not turn into a ledger edit."""
    item = rel(item) if Path(str(item)).is_absolute() else str(item)
    gen = rel(generator) if Path(str(generator)).is_absolute() else str(generator)
    if not gen.startswith("assets/src/"):
        raise ValueError(f"generator {gen} must live under assets/src/")
    source = f"generated by {gen}" + (f" (seed {seed})" if seed is not None else "") + f"; script written by {writer}"
    if note:
        source += f"; {note}"
    path = _target(group)
    rows = _read(path)
    old = next((r for r in rows if r and r[0] == item), None)
    today = date or datetime.date.today().isoformat()
    row = [item, kind, source, licence, url, used_in, today, "yes" if verified else "no"]
    for prev in (old, _ledger_row(item)):
        if prev and len(prev) == len(HEADER) and prev[:6] == row[:6] and prev[7] == row[7]:
            row[6] = prev[6]                  # unchanged: keep the original date so the file does not churn
            break
    rows = [r for r in rows if r and r[0] != item] + [row]
    rows.sort(key=lambda r: r[0])
    buf = io.StringIO()
    csv.writer(buf, lineterminator="\n").writerows(rows)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(buf.getvalue(), encoding="utf-8")
    return row


_LEDGER_CACHE = None


def _ledger_row(item):
    global _LEDGER_CACHE
    if _LEDGER_CACHE is None:
        _LEDGER_CACHE = {r[0]: r for r in _read(ROOT / "assets" / "LEDGER.csv")[1:] if r}
    return _LEDGER_CACHE.get(item)


def remove(group, item):
    """Drop the row for `item` from the group's row file (when a generator stops making that file)."""
    path = _target(group)
    if not path.exists():
        return
    rows = [r for r in _read(path) if r and r[0] != str(item)]
    buf = io.StringIO()
    csv.writer(buf, lineterminator="\n").writerows(rows)
    path.write_text(buf.getvalue(), encoding="utf-8")


__all__ = ["add", "remove", "HEADER", "FRAG_DIR", "BUILD_DIR", "ROOT"]
